#!/usr/bin/env python3
import parse_orca as pars
import os, sys
import numpy as np

def calc(comname, writexyz, N, n, q, fchk, get, aulen):
    with open(writexyz, 'w') as f:
        f.write('{}\n\n'.format(N))
        printcoord = ''
        for i in range(N):
            f.write('{0:<2s} {1[0]:>20.16f} {1[1]:>20.16f} {1[2]:>20.16f} \n'.format(n[i], np.multiply(q[3*i:3*i+3], aulen)))
    os.system('orca {0}.inp > {0}.out'.format(comname))
    return pars.parse_orca(comname, get)
   
def initcalc(comname, writexyz, N, n, q, fchk, get, aulen, init):
    with open(writexyz, 'w') as f:
        f.write('{}\n\n'.format(N))
        for i in range(N):
            f.write('{0:<2s} {1[0]:>20.16f} {1[1]:>20.16f} {1[2]:>20.16f} \n'.format(n[i], np.multiply(q[3*i:3*i+3], aulen)))# init gives coord in Angstrom but required is in Bohr
    os.system('orca {1}{0}.inp > {1}{0}.out'.format(comname, init))
    os.system('cp {1}{0}.gbw {0}.gbw'.format(comname, init))
    return pars.parse_orca('{0}{1}'.format(init, comname), get)
